/** Opt-in client-only observation of an existing saved gallery COPY. No block/entity authoring. */
public final class GalleryBenchmarkV127 implements ClientModInitializer {
 private static final Gson JSON=new GsonBuilder().setPrettyPrinting().create();
 private final JsonObject report=new JsonObject();private final JsonArray results=new JsonArray(),frames=new JsonArray(),memory=new JsonArray(),observations=new JsonArray();
 private static GalleryBenchmarkV127 INSTANCE; private Path directory,output;private JsonObject input;private List<JsonObject> route;private String phase="BOOT";private int index,round,ticks,stable;private boolean active,done,screenshotSaved;private long began=System.nanoTime(),phaseBegan;private Sample sampling;
 private volatile Sample serverSample;private Sample serverStartedSample;private long serverStarted;
 private static final class Sample {
  final String kind,name;final List<Long> frameTimes=new ArrayList<>(),serverTimes=new ArrayList<>();long last,started=System.nanoTime(),focusedFrames,unfocusedFrames,iconifiedFrames;boolean closed;
  Sample(String kind,String name){this.kind=kind;this.name=name;}
  synchronized void frame(long now,boolean focused,boolean iconified){if(closed)return;if(focused)focusedFrames++;else unfocusedFrames++;if(iconified)iconifiedFrames++;if(last!=0){if(frameTimes.size()>=250000)throw new IllegalStateException("Bounded frame sample limit reached");frameTimes.add(now-last);}last=now;}
  synchronized void server(long nanos){if(!closed&&serverTimes.size()<250000)serverTimes.add(nanos);}
  synchronized JsonObject finish(){closed=true;var row=new JsonObject();row.addProperty("kind",kind);row.addProperty("station",name);row.addProperty("wallSeconds",(System.nanoTime()-started)/1e9);row.add("actualWorldRenderFrameIntervals",stats(frameTimes,true));row.add("actualIntegratedServerTickDurations",stats(serverTimes,false));var focus=new JsonObject();focus.addProperty("focusedRenderCallbacks",focusedFrames);focus.addProperty("unfocusedRenderCallbacks",unfocusedFrames);focus.addProperty("iconifiedRenderCallbacks",iconifiedFrames);focus.addProperty("method","Actual GLFW_FOCUSED and GLFW_ICONIFIED queried on the render thread for each sampled render callback; observation only, no focus control");row.add("actualWindowFocusSamples",focus);return row;}
 }
 @Override public void onInitializeClient(){try{
  var client=MinecraftClient.getInstance();directory=client.runDirectory.toPath().toAbsolutePath().normalize();var marker=directory.resolve("client-capture-input.json");if(!Files.isRegularFile(marker,LinkOption.NOFOLLOW_LINKS))return;
  input=JsonParser.parseString(Files.readString(marker)).getAsJsonObject();if(!input.has("v127GalleryBenchmark")||!input.get("v127GalleryBenchmark").getAsBoolean())return;
  check(input.get("newGalleryOnly").getAsBoolean(),"Explicit existing-copy gallery marker required");var paths=FabricLoader.getInstance().getModContainer("bloodborne_dw").orElseThrow().getOrigin().getPaths();check(paths.size()==1&&sha(paths.get(0)).equals(input.get("productionJarSha256").getAsString()),"Actual production JAR must match input SHA");
  route=new ArrayList<>();input.getAsJsonArray("frames").forEach(row->route.add(row.getAsJsonObject()));check(route.size()>=6&&route.size()<=16,"Exactly six explicit gallery/city stations required");
  output=directory.resolve("v127-gallery-benchmark.json");check(!Files.exists(output),"Fresh evidence output required");report.addProperty("schema","dreamwalker-v127-new-gallery-benchmark-v1");report.addProperty("productionJarSha256",input.get("productionJarSha256").getAsString());report.addProperty("gallerySourceZipSha256",input.get("gallerySourceZipSha256").getAsString());report.addProperty("galleryManifestSha256",input.get("galleryManifestSha256").getAsString());report.addProperty("galleryCreated",true);report.addProperty("blockOrEntityAuthoring",false);report.addProperty("physicalMouseKeyboardInput","NOT_RUN");report.addProperty("performanceAcceptance","PENDING_ROOT_REVIEW_RAW_MEASUREMENTS");report.addProperty("method","Actual world-render END timestamps and integrated server START/END tick timestamps, six native camera command viewpoints of existing gallery/city copy, cold first visits and warmed stationary views; real framebuffer captures and ordinary shutdown save");report.add("stationMeasurements",results);report.add("frames",frames);report.add("nativeHeapSnapshots",memory);report.add("actualStationObjects",observations);
  INSTANCE=this;active=true;write("WAITING_FOR_EXISTING_WORLD");
  WorldRenderEvents.END.register(context->{if(!active||done)return;try{if(!report.has("graphics"))graphics(client);if(client.world!=null&&client.player!=null&&client.currentScreen==null&&!client.isPaused()&&sampling!=null){long handle=client.getWindow().getHandle();sampling.frame(System.nanoTime(),GLFW.glfwGetWindowAttrib(handle,GLFW.GLFW_FOCUSED)==GLFW.GLFW_TRUE,GLFW.glfwGetWindowAttrib(handle,GLFW.GLFW_ICONIFIED)==GLFW.GLFW_TRUE);}}catch(Throwable failure){fail(failure);}});
  ServerTickEvents.START_SERVER_TICK.register(server->{serverStartedSample=serverSample;serverStarted=System.nanoTime();});ServerTickEvents.END_SERVER_TICK.register(server->{if(serverStartedSample!=null){serverStartedSample.server(System.nanoTime()-serverStarted);serverStartedSample=null;}});
  ClientTickEvents.END_CLIENT_TICK.register(this::tick);
 }catch(Throwable failure){fail(failure);}}
 private void tick(MinecraftClient client){if(!active||done)return;try{
  check(System.nanoTime()-began<900_000_000_000L,"Existing-gallery observation timeout");if(phase.equals("QUIT")){if(++ticks>=30){report.addProperty("normalSaveShutdownRequested",true);write("PASS_ENGINE_GALLERY_BENCHMARK_REQUIRES_ROOT_REVIEW_AND_SAVE_VERIFICATION");client.scheduleStop();done=true;}return;}
  lockCamera(client);if(phase.equals("WARM"))check(client.world!=null&&client.player!=null&&client.currentScreen==null&&!client.isPaused(),"Measured view interrupted by GUI, pause or world departure");if(client.world==null||client.player==null||client.currentScreen!=null||client.isPaused())return;ticks++;
  switch(phase){
   case "BOOT"->{if(ticks<40)return;
    if(input.has("worldEditQa")&&input.get("worldEditQa").getAsBoolean()){
        var nativeServer=client.getServer();var playerUuid=client.player.getUuid();
        var qa=java.util.concurrent.CompletableFuture.supplyAsync(()->GalleryWorldEditQa.run(nativeServer,nativeServer.getPlayerManager().getPlayer(playerUuid)),nativeServer).join();
        report.add("actualWorldEditCommandProof",qa);input.addProperty("worldEditQa",false);
    }var server=client.getServer();check(server!=null,"Existing-copy integrated server required");var world=server.getSavePath(WorldSavePath.ROOT).toAbsolutePath().normalize();check(world.startsWith(directory.resolve("saves")),"Benchmark world must be the runner's own copied save");check(sha(world.resolve("gallery-manifest.json")).equals(input.get("galleryManifestSha256").getAsString()),"The opened world is the exact existing V12.6 gallery");report.addProperty("secondsFromAddonInitializationUntilReadyWorld",(System.nanoTime()-began)/1e9);report.addProperty("coldStartupScope","World ready after addon initialization; includes client model loading/world startup, not process launch or uncapped hardware capability");report.addProperty("worldCopyPath",world.toString());heap(client,"world_open_before_tour");client.player.networkHandler.sendChatCommand("gamemode spectator");stage("MODE");}
   case "MODE"->{if(!client.player.isSpectator())return;index=0;round=0;navigate(client);}
   case "NAVIGATE"->{stable=atCamera(client)&&loaded(client)?stable+1:0;if(stable<90)return;verify(client);if(round==0){closeSample();if(++index<route.size())navigate(client);else{round=1;index=0;navigate(client);}}else{sampling=new Sample("WARM_STATIONARY",name());serverSample=sampling;stage("WARM");}}
   case "WARM"->{check(atCamera(client)&&loaded(client),"Camera and representative chunks stay present while measuring "+name());if(System.nanoTime()-phaseBegan<input.get("warmSecondsPerStation").getAsInt()*1_000_000_000L)return;closeSample();heap(client,"after_warm_"+name());screenshotSaved=false;var station=route.get(index);var file=station.get("fileName").getAsString();ScreenshotRecorder.saveScreenshot(directory.toFile(),file,client.getFramebuffer(),message->client.execute(()->screenshotSaved=true));stage("SCREENSHOT");}
   case "SCREENSHOT"->{if(!screenshotSaved)return;var file=route.get(index).get("fileName").getAsString();var path=directory.resolve("screenshots").resolve(file);check(Files.isRegularFile(path)&&Files.size(path)>1000,"Native framebuffer PNG saved");var row=new JsonObject();row.addProperty("fileName",file);row.addProperty("sha256",sha(path));row.addProperty("bytes",Files.size(path));row.addProperty("station",name());row.addProperty("status","PASS_CAPTURE_PIXEL_REVIEW_REQUIRED");frames.add(row);write("RUNNING");if(++index<route.size())navigate(client);else{check(frames.size()==route.size(),"All six native frames captured");heap(client,"tour_complete_before_ordinary_save");report.addProperty("existingGalleryOpened","PASS");report.addProperty("sixStationObjectChecks","PASS");report.addProperty("warmedMeasuredSecondsAtLeast",route.size()*input.get("warmSecondsPerStation").getAsInt());report.addProperty("serverTimingMethod","Actual integrated server tick START/END events, no guessed getTickTimes API");report.addProperty("saveAndReopen","PENDING_NORMAL_SHUTDOWN_AND_SEPARATE_REOPEN");report.addProperty("pixelReview","NOT_RUN");stage("QUIT");}}
   default->throw new IllegalStateException("Unknown benchmark phase "+phase);
  }
 }catch(Throwable failure){fail(failure);}}
 private void navigate(MinecraftClient client){GLFW.glfwFocusWindow(client.getWindow().getHandle());var c=route.get(index).getAsJsonArray("camera");client.player.networkHandler.sendChatCommand("tp @s "+c.get(0)+" "+c.get(1)+" "+c.get(2)+" "+c.get(3)+" "+c.get(4));stage("NAVIGATE");if(round==0){sampling=new Sample("COLD_FIRST_VISIT_LOADING_AND_SETTLE",name());serverSample=sampling;}else{sampling=null;serverSample=null;}}
 private boolean atCamera(MinecraftClient client){var c=route.get(index).getAsJsonArray("camera");return client.player.getPos().squaredDistanceTo(new Vec3d(c.get(0).getAsDouble(),c.get(1).getAsDouble(),c.get(2).getAsDouble()))<.01&&Math.abs(MathHelper.wrapDegrees(client.player.getYaw()-c.get(3).getAsFloat()))<.75&&Math.abs(client.player.getPitch()-c.get(4).getAsFloat())<.75;}
 private boolean loaded(MinecraftClient client){var c=route.get(index).getAsJsonArray("camera");if(!client.world.isChunkLoaded(BlockPos.ofFloored(c.get(0).getAsDouble(),c.get(1).getAsDouble(),c.get(2).getAsDouble())))return false;for(var raw:route.get(index).getAsJsonArray("rootChecks")){var p=raw.getAsJsonObject().getAsJsonArray("root");if(!client.world.isChunkLoaded(new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt())))return false;}return true;}
 private void verify(MinecraftClient client){var station=route.get(index);var row=new JsonObject();row.addProperty("station",name());row.addProperty("round",round==0?"cold":"warm");var owners=new JsonArray();
  for(var raw:station.getAsJsonArray("rootChecks")){var expected=raw.getAsJsonObject();var p=expected.getAsJsonArray("root");var pos=new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt(),p.get(2).getAsInt());var state=client.world.getBlockState(pos);var be=client.world.getBlockEntity(pos);check(be instanceof CompositeBlockEntity own&&own.resident()!=null&&own.resident().instanceId().toString().equals(expected.get("uuid").getAsString()),"Actual saved owner UUID synced at "+pos+" station "+name());var registry=Registries.BLOCK.getId(state.getBlock()).toString();check(registry.equals(expected.get("registry").getAsString()),"Exact expected registry at "+pos+": "+registry);var properties=new JsonObject();for(var entry:state.getEntries().entrySet())properties.addProperty(entry.getKey().getName(),String.valueOf(entry.getValue()).toLowerCase(Locale.ROOT));for(var entry:expected.entrySet())if(!Set.of("root","registry","uuid").contains(entry.getKey()))check(properties.has(entry.getKey())&&properties.get(entry.getKey()).getAsString().equals(entry.getValue().getAsString()),"Exact expected state "+entry.getKey()+" at "+pos+" actual="+properties);var actual=new JsonObject();actual.add("root",p);actual.addProperty("registry",registry);actual.add("properties",properties);actual.addProperty("ownerUuid",((CompositeBlockEntity)be).resident().instanceId().toString());actual.addProperty("typedNativeBlockEntitySnbt",be.createNbt().toString());owners.add(actual);}
  for(var raw:station.getAsJsonArray("entityChecks")){var expected=raw.getAsJsonObject();boolean found=false;for(var entity:client.world.getEntities())if(entity.getUuid().toString().equals(expected.get("uuid").getAsString())){found=true;var registry=Registries.ENTITY_TYPE.getId(entity.getType()).toString();check(registry.equals(expected.get("registry").getAsString()),"Exact expected RP registry: "+registry);var actual=new JsonObject();actual.addProperty("entityUuid",entity.getUuid().toString());actual.addProperty("registry",registry);owners.add(actual);break;}check(found,"Actual saved entity UUID synced at station "+name());}row.add("owners",owners);observations.add(row);}
 private void closeSample(){if(sampling!=null){var row=sampling.finish();check(row.getAsJsonObject("actualWorldRenderFrameIntervals").get("sampleCount").getAsInt()>1,"Real rendered frame samples exist: "+name());results.add(row);sampling=null;serverSample=null;}}
 private void graphics(MinecraftClient client){var row=new JsonObject();row.addProperty("GLVendor",GL11.glGetString(GL11.GL_VENDOR));row.addProperty("GLRendererDevice",GL11.glGetString(GL11.GL_RENDERER));row.addProperty("GLVersion",GL11.glGetString(GL11.GL_VERSION));int[] viewport=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,viewport);row.add("actualGlViewport",JSON.toJsonTree(viewport));row.addProperty("framebufferWidth",client.getWindow().getFramebufferWidth());row.addProperty("framebufferHeight",client.getWindow().getFramebufferHeight());row.addProperty("maxFpsOption",client.options.getMaxFps().getValue());row.addProperty("vsyncOption",client.options.getEnableVsync().getValue());row.addProperty("renderDistanceChunks",client.options.getViewDistance().getValue());row.addProperty("simulationDistanceChunks",client.options.getSimulationDistance().getValue());row.addProperty("graphicsMode",client.options.getGraphicsMode().getValue().toString());row.add("actualWindowFocus",windowFocus(client));row.addProperty("capturedOnActualWorldRenderEnd",true);report.add("graphics",row);}
 private void heap(MinecraftClient client,String name){var r=Runtime.getRuntime();var row=new JsonObject();row.addProperty("name",name);row.addProperty("usedHeapBytesObserved",r.totalMemory()-r.freeMemory());row.addProperty("committedHeapBytes",r.totalMemory());row.addProperty("maximumHeapBytes",r.maxMemory());row.addProperty("forcedGc",false);row.add("actualWindowFocus",windowFocus(client));row.add("publishedOwnerGeometry",JSON.toJsonTree(CompositeShapeSnapshots.metrics(client.world)));try{row.add("newSourceVisibility",JSON.toJsonTree(Class.forName("dev.dreamwalker.bloodbornedw.composite.CompositeVisualBoundsV127").getMethod("snapshot").invoke(null)));}catch(ReflectiveOperationException absent){row.addProperty("newSourceVisibility","NOT_INSTALLED_HISTORICAL_JAR");}var gc=new JsonArray();for(var bean:java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()){var g=new JsonObject();g.addProperty("name",bean.getName());g.addProperty("collections",bean.getCollectionCount());g.addProperty("collectionMilliseconds",bean.getCollectionTime());gc.add(g);}row.add("garbageCollectors",gc);row.addProperty("nonHeapUsedBytes",java.lang.management.ManagementFactory.getMemoryMXBean().getNonHeapMemoryUsage().getUsed());memory.add(row);report.addProperty("memoryScope","Observed native client JVM heap includes the integrated server; not process RSS or a full-city RAM estimate");}
 private static JsonObject windowFocus(MinecraftClient client){long handle=client.getWindow().getHandle();var row=new JsonObject();row.addProperty("focused",GLFW.glfwGetWindowAttrib(handle,GLFW.GLFW_FOCUSED)==GLFW.GLFW_TRUE);row.addProperty("iconified",GLFW.glfwGetWindowAttrib(handle,GLFW.GLFW_ICONIFIED)==GLFW.GLFW_TRUE);row.addProperty("focusControl",false);return row;}
 private static JsonObject stats(List<Long> input,boolean frames){var row=new JsonObject();row.addProperty("sampleCount",input.size());if(input.isEmpty()){row.addProperty("status","NO_SAMPLES");return row;}var sorted=new ArrayList<>(input);sorted.sort(Long::compare);double total=input.stream().mapToDouble(Long::doubleValue).sum();row.addProperty("meanMilliseconds",total/input.size()/1e6);for(var p:new double[]{.50,.95,.99})row.addProperty("p"+Math.round(p*100)+"Milliseconds",sorted.get(Math.max(0,(int)Math.ceil(p*sorted.size())-1))/1e6);row.addProperty("maxMilliseconds",sorted.get(sorted.size()-1)/1e6);row.addProperty("samplesOver50ms",input.stream().filter(n->n>50_000_000).count());row.addProperty("samplesOver100ms",input.stream().filter(n->n>100_000_000).count());row.addProperty("sampledSeconds",total/1e9);if(frames)row.addProperty("averageObservedFps",input.size()*1e9/total);row.addProperty("status","ACTUAL_NATIVE_MEASUREMENTS_REQUIRE_REVIEW");return row;}
 private String name(){return route.get(index).get("key").getAsString();}
 private void stage(String name){phase=name;ticks=0;stable=0;phaseBegan=System.nanoTime();}
 private void write(String status)throws Exception{report.addProperty("status",status);report.addProperty("phase",phase);report.addProperty("stationIndex",index);report.addProperty("updatedUtc",Instant.now().toString());Files.writeString(output,JSON.toJson(report));}
 private void fail(Throwable failure){done=true;sampling=null;serverSample=null;report.addProperty("failure",failure.toString());try{if(output!=null)write("FAIL_ENGINE_GALLERY_BENCHMARK");}catch(Exception ignored){}failure.printStackTrace();MinecraftClient.getInstance().execute(()->MinecraftClient.getInstance().scheduleStop());}
 private static String sha(Path path)throws Exception{var digest=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(path)){var buffer=new byte[65536];for(int n;(n=in.read(buffer))!=-1;)digest.update(buffer,0,n);}return HexFormat.of().formatHex(digest.digest());}
 public static void lockCamera(MinecraftClient client){
  var self=INSTANCE;if(self==null||!self.active||self.done||client.player==null||self.route==null||self.index>=self.route.size()||!Set.of("NAVIGATE","SETTLE","WARM","SCREENSHOT").contains(self.phase))return;
  var c=self.route.get(self.index).getAsJsonArray("camera");float yaw=c.get(3).getAsFloat(),pitch=c.get(4).getAsFloat();client.player.setYaw(yaw);client.player.setPitch(pitch);client.player.prevYaw=yaw;client.player.prevPitch=pitch;
  if(self.phase.equals("WARM")||self.phase.equals("SCREENSHOT")){client.player.setPosition(c.get(0).getAsDouble(),c.get(1).getAsDouble(),c.get(2).getAsDouble());client.player.setVelocity(Vec3d.ZERO);}
 }
 private static void check(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}
}
